package io.invenlio.catalog;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.data.domain.Page;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/categories") class CategoryController {private final CatalogService service;CategoryController(CatalogService s){service=s;}@PostMapping CategoryView create(@Valid @RequestBody Request r){return view(service.createCategory(r.name(),r.parentId()));}@GetMapping Page<CategoryView> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.categories(page,size).map(CategoryController::view);}@PatchMapping("/{id}")CategoryView update(@PathVariable UUID id,@Valid @RequestBody Request r){return view(service.updateCategory(id,r.name(),r.parentId(),r.version()));}@PostMapping("/{id}/archive")CategoryView archive(@PathVariable UUID id){return view(service.archiveCategory(id));}static CategoryView view(Category c){return new CategoryView(c.id(),c.name(),c.slug(),c.parent(),c.status().name(),c.created(),c.updated(),c.version());}record Request(@NotBlank @Size(max=120)String name,UUID parentId,@PositiveOrZero long version){}record CategoryView(UUID id,String name,String slug,UUID parentId,String status,Instant createdAt,Instant updatedAt,long version){}}
